INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-001','verb-to-be','Pre-A1',1,'Tôi là học sinh.','I am a student.',NULL,'["I", "be", "student"]','I đi với am.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-002','verb-to-be','Pre-A1',1,'Cô ấy là giáo viên của tôi.','She is my teacher.',NULL,'["she", "be", "my", "teacher"]','He/she/it đi với is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-003','verb-to-be','Pre-A1',1,'Con mèo ở dưới gầm giường.','The cat is under the bed.',NULL,'["cat", "be", "under", "bed"]','Nói vị trí: S + is/are + giới từ + nơi chốn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-004','verb-to-be','Pre-A1',1,'Chúng tôi rất vui.','We are very happy.',NULL,'["we", "be", "very", "happy"]','We/you/they đi với are.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-005','verb-to-be','Pre-A1',2,'Anh ấy không cao.','He is not tall.',NULL,'["he", "be", "not", "tall"]','Phủ định: is/are/am + not.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-006','verb-to-be','Pre-A1',2,'Họ không ở trường.','They are not at school.',NULL,'["they", "be", "not", "at", "school"]','Phủ định: they + are not (aren''t).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-007','verb-to-be','Pre-A1',2,'Bạn có mệt không?','Are you tired?',NULL,'["you", "be", "tired"]','Câu hỏi: đưa am/is/are lên trước chủ ngữ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-008','verb-to-be','Pre-A1',2,'Mẹ của bạn có ở nhà không?','Is your mother at home?','["Is your mum at home?", "Is your mom at home?"]','["your", "mother", "be", "at", "home"]','Câu hỏi với he/she: Is + S + ...?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-009','verb-to-be','Pre-A1',3,'Những quả táo này rất ngọt.','These apples are very sweet.',NULL,'["this", "apple", "be", "very", "sweet"]','Chủ ngữ số nhiều (these apples) đi với are.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-verb-to-be-010','verb-to-be','Pre-A1',3,'Nó không phải là con chó của tôi.','It is not my dog.',NULL,'["it", "be", "not", "my", "dog"]','It đi với is; phủ định thêm not.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-001','articles-a-an','Pre-A1',1,'Tôi có một con mèo.','I have a cat.',NULL,'["I", "have", "cat"]','cat bắt đầu bằng âm phụ âm → a.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-002','articles-a-an','Pre-A1',1,'Cô ấy có một quả táo.','She has an apple.',NULL,'["she", "have", "apple"]','apple bắt đầu bằng nguyên âm → an.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-003','articles-a-an','Pre-A1',1,'Đó là một quả trứng.','It is an egg.','["That is an egg."]','["it", "be", "egg"]','egg bắt đầu bằng nguyên âm → an.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-004','articles-a-an','Pre-A1',1,'Anh ấy là một bác sĩ.','He is a doctor.',NULL,'["he", "be", "doctor"]','Nói nghề nghiệp cần a/an trước danh từ số ít.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-005','articles-a-an','Pre-A1',2,'Tôi muốn một cái ô.','I want an umbrella.',NULL,'["I", "want", "umbrella"]','umbrella bắt đầu bằng nguyên âm → an.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-006','articles-a-an','Pre-A1',2,'Mẹ tôi là một y tá.','My mother is a nurse.','["My mum is a nurse.", "My mom is a nurse."]','["my", "mother", "be", "nurse"]','nurse bắt đầu bằng âm phụ âm → a.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-007','articles-a-an','Pre-A1',2,'Bố tôi có một chiếc ô tô mới.','My father has a new car.','["My dad has a new car."]','["my", "father", "have", "new", "car"]','Xét âm của từ đứng ngay sau mạo từ: new → a.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-008','articles-a-an','Pre-A1',2,'Đây là một cái áo màu cam.','This is an orange shirt.',NULL,'["this", "be", "orange", "shirt"]','Từ ngay sau mạo từ là orange (nguyên âm) → an.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-009','articles-a-an','Pre-A1',3,'Cậu ấy là một cậu bé trung thực.','He is an honest boy.',NULL,'["he", "be", "honest", "boy"]','honest có h câm, đọc bằng nguyên âm → an.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-articles-a-an-010','articles-a-an','Pre-A1',3,'Anh trai tôi là sinh viên đại học.','My brother is a university student.',NULL,'["my", "brother", "be", "university", "student"]','university đọc bằng âm /j/ (phụ âm) → a.',0,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-001','plural-nouns','Pre-A1',1,'Tôi có hai con chó.','I have two dogs.',NULL,'["I", "have", "two", "dog"]','Số nhiều thường thêm -s: dog → dogs.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-002','plural-nouns','Pre-A1',1,'Có ba cái hộp trên bàn.','There are three boxes on the table.',NULL,'["there", "be", "three", "box", "on", "table"]','Danh từ tận cùng -x thêm -es: boxes.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-003','plural-nouns','Pre-A1',1,'Những đứa trẻ rất vui.','The children are very happy.','["The kids are very happy."]','["child", "be", "very", "happy"]','Bất quy tắc: child → children.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-004','plural-nouns','Pre-A1',1,'Hai bàn chân tôi lạnh.','My feet are cold.',NULL,'["my", "foot", "be", "cold"]','Bất quy tắc: foot → feet.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-005','plural-nouns','Pre-A1',2,'Cô ấy có năm quả cà chua.','She has five tomatoes.',NULL,'["she", "have", "five", "tomato"]','Tận cùng -o: tomato → tomatoes.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-006','plural-nouns','Pre-A1',2,'Những chiếc lá màu vàng.','The leaves are yellow.',NULL,'["leaf", "be", "yellow"]','Tận cùng -f: leaf → leaves.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-007','plural-nouns','Pre-A1',2,'Có nhiều người trong công viên.','There are many people in the park.','["There are a lot of people in the park.", "There are lots of people in the park."]','["there", "be", "many", "person", "in", "park"]','Bất quy tắc: person → people.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-008','plural-nouns','Pre-A1',2,'Tôi đánh răng hai lần mỗi ngày.','I brush my teeth twice a day.','["I brush my teeth twice every day.", "I brush my teeth two times a day."]','["I", "brush", "my", "tooth", "twice", "day"]','Bất quy tắc: tooth → teeth.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-plural-nouns-009','plural-nouns','Pre-A1',3,'Những con dao ở trong ngăn kéo.','The knives are in the drawer.',NULL,'["knife", "be", "in", "drawer"]','Tận cùng -fe: knife → knives.',1,'live','seed','2026-10-27T00:00:00.000Z');
