INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-001','there-is-are','Pre-A1',1,'Có một con mèo trong phòng.','There is a cat in the room.',NULL,'["there", "be", "cat", "in", "room"]','Một vật số ít → There is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-002','there-is-are','Pre-A1',1,'Có hai quyển sách trên bàn.','There are two books on the table.',NULL,'["there", "be", "two", "book", "on", "table"]','Nhiều vật → There are.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-003','there-is-are','Pre-A1',1,'Có một cái cây trong vườn.','There is a tree in the garden.',NULL,'["there", "be", "tree", "in", "garden"]','Danh từ số ít → There is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-004','there-is-are','Pre-A1',1,'Có nhiều học sinh trong lớp tôi.','There are many students in my class.','["There are a lot of students in my class.", "There are lots of students in my class."]','["there", "be", "many", "student", "in", "my", "class"]','Danh từ số nhiều → There are.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-005','there-is-are','Pre-A1',2,'Không có sữa trong tủ lạnh.','There is no milk in the fridge.','["There isn''t any milk in the fridge."]','["there", "be", "no", "milk", "in", "fridge"]','Danh từ không đếm được (milk) → There is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-006','there-is-are','Pre-A1',2,'Không có cái ghế nào trong phòng.','There are no chairs in the room.','["There aren''t any chairs in the room."]','["there", "be", "no", "chair", "in", "room"]','Phủ định số nhiều: There are no / There aren''t any.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-007','there-is-are','Pre-A1',2,'Có một con chó trong nhà bạn không?','Is there a dog in your house?',NULL,'["there", "be", "dog", "in", "your", "house"]','Câu hỏi: Is there + danh từ số ít?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-008','there-is-are','Pre-A1',2,'Có quả táo nào trong túi không?','Are there any apples in the bag?',NULL,'["there", "be", "any", "apple", "in", "bag"]','Câu hỏi số nhiều: Are there any + N?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-009','there-is-are','Pre-A1',3,'Có một bức tranh đẹp trên tường.','There is a beautiful picture on the wall.','["There is a nice picture on the wall.", "There is a pretty picture on the wall."]','["there", "be", "beautiful", "picture", "on", "wall"]','Danh từ số ít → There is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-there-is-are-010','there-is-are','Pre-A1',3,'Có ba con chim trên cây.','There are three birds in the tree.','["There are three birds on the tree."]','["there", "be", "three", "bird", "in", "tree"]','Nhiều vật → There are.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-001','can-ability','Pre-A1',1,'Tôi có thể bơi.','I can swim.',NULL,'["I", "can", "swim"]','can + động từ nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-002','can-ability','Pre-A1',1,'Cô ấy có thể hát rất hay.','She can sing very well.',NULL,'["she", "can", "sing", "very", "well"]','can không thêm -s với she/he.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-003','can-ability','Pre-A1',1,'Con mèo có thể leo cây.','The cat can climb trees.','["The cat can climb a tree."]','["cat", "can", "climb", "tree"]','can + động từ nguyên thể (climb).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-004','can-ability','Pre-A1',1,'Anh ấy không thể nấu ăn.','He can''t cook.',NULL,'["he", "can", "not", "cook"]','Phủ định: can''t (cannot) + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-005','can-ability','Pre-A1',2,'Chúng tôi không biết nói tiếng Pháp.','We can''t speak French.',NULL,'["we", "can", "not", "speak", "French"]','biết làm gì = can; không biết = can''t.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-006','can-ability','Pre-A1',2,'Bạn có thể đi xe đạp không?','Can you ride a bike?','["Can you ride a bicycle?"]','["you", "can", "ride", "bike"]','Câu hỏi: Can + S + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-007','can-ability','Pre-A1',2,'Bố bạn có biết lái ô tô không?','Can your father drive a car?','["Can your dad drive a car?"]','["your", "father", "can", "drive", "car"]','Câu hỏi: Can + S + V? (không dùng Does).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-008','can-ability','Pre-A1',2,'Em gái tôi biết đọc nhưng không biết viết.','My sister can read but she can''t write.','["My sister can read but can''t write.", "My little sister can read but she can''t write.", "My little sister can read but can''t write.", "My younger sister can read but she can''t write.", "My younger sister can read but can''t write."]','["my", "sister", "can", "read", "not", "write"]','can và can''t đều đi với động từ nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-009','can-ability','Pre-A1',3,'Những con chim có thể bay rất cao.','The birds can fly very high.','["Birds can fly very high."]','["bird", "can", "fly", "very", "high"]','can dùng cho mọi chủ ngữ, động từ giữ nguyên.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-can-ability-010','can-ability','Pre-A1',3,'Con cá không thể đi bộ.','The fish can''t walk.','["Fish can''t walk."]','["fish", "can", "not", "walk"]','can''t + động từ nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-001','present-simple','A1',1,'Tôi ăn sáng mỗi ngày.','I have breakfast every day.','["I eat breakfast every day.", "Every day I have breakfast.", "Every day I eat breakfast."]','["I", "have", "breakfast", "every day"]','Thói quen hằng ngày → hiện tại đơn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-002','present-simple','A1',1,'Cô ấy đi học bằng xe buýt.','She goes to school by bus.',NULL,'["she", "go", "school", "by", "bus"]','She/he/it: động từ thêm -s/-es (go → goes).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-003','present-simple','A1',1,'Anh ấy thích bóng đá.','He likes football.','["He likes soccer."]','["he", "like", "football"]','He + động từ thêm -s: likes.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-004','present-simple','A1',1,'Bố tôi làm việc ở bệnh viện.','My father works in a hospital.','["My dad works in a hospital.", "My father works at a hospital.", "My dad works at a hospital."]','["my", "father", "work", "in", "hospital"]','Chủ ngữ số ít → works.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-005','present-simple','A1',2,'Tôi không uống cà phê.','I don''t drink coffee.',NULL,'["I", "drink", "coffee", "not"]','Phủ định với I: don''t + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-006','present-simple','A1',2,'Cô ấy không xem tivi vào buổi sáng.','She doesn''t watch TV in the morning.','["She doesn''t watch television in the morning.", "In the morning she doesn''t watch TV."]','["she", "watch", "TV", "in the morning", "not"]','She/he: doesn''t + V nguyên thể (không thêm -s).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-007','present-simple','A1',2,'Bạn có nuôi thú cưng không?','Do you have a pet?','["Have you got a pet?"]','["you", "have", "pet"]','Câu hỏi: Do + you + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-008','present-simple','A1',2,'Anh trai bạn có chơi đàn ghi-ta không?','Does your brother play the guitar?',NULL,'["your", "brother", "play", "guitar"]','Câu hỏi với ngôi thứ ba số ít: Does + S + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-009','present-simple','A1',3,'Mặt trời mọc ở phía đông.','The sun rises in the east.',NULL,'["sun", "rise", "in", "east"]','Sự thật hiển nhiên → hiện tại đơn; the sun → rises.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-simple-010','present-simple','A1',3,'Mẹ tôi không làm việc vào Chủ nhật.','My mother doesn''t work on Sundays.','["My mum doesn''t work on Sundays.", "My mom doesn''t work on Sundays.", "My mother doesn''t work on Sunday.", "My mum doesn''t work on Sunday.", "My mom doesn''t work on Sunday."]','["my", "mother", "work", "on", "Sunday", "not"]','My mother = she → doesn''t + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-001','present-continuous','A1',1,'Bây giờ tôi đang đọc sách.','I am reading a book now.','["I am reading a book right now.", "I am reading a book at the moment.", "Now I am reading a book.", "Right now I am reading a book."]','["I", "read", "book", "now"]','Đang diễn ra: am/is/are + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-002','present-continuous','A1',1,'Cô ấy đang nấu bữa tối.','She is cooking dinner.','["She is making dinner."]','["she", "cook", "dinner"]','She + is + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-003','present-continuous','A1',1,'Những đứa trẻ đang chơi trong vườn.','The children are playing in the garden.','["The kids are playing in the garden."]','["child", "play", "in", "garden"]','Chủ ngữ số nhiều + are + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-004','present-continuous','A1',1,'Trời đang mưa.','It is raining.',NULL,'["it", "rain"]','Thời tiết dùng chủ ngữ it: It is raining.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-005','present-continuous','A1',2,'Bây giờ anh ấy không ngủ.','He isn''t sleeping now.','["He isn''t sleeping right now.", "He isn''t sleeping at the moment.", "Now he isn''t sleeping."]','["he", "sleep", "not", "now"]','Phủ định: isn''t/aren''t + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-006','present-continuous','A1',2,'Lúc này chúng tôi không xem tivi.','We aren''t watching TV at the moment.','["We aren''t watching TV now.", "We aren''t watching TV right now.", "At the moment we aren''t watching TV.", "We aren''t watching television at the moment."]','["we", "watch", "TV", "not", "at the moment"]','We + aren''t + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-007','present-continuous','A1',2,'Bạn có đang làm bài tập về nhà không?','Are you doing your homework?','["Are you doing homework?"]','["you", "do", "homework"]','Câu hỏi: Are + you + V-ing?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-008','present-continuous','A1',2,'Bố bạn đang làm gì?','What is your father doing?','["What is your dad doing?"]','["what", "your", "father", "do"]','Wh- + is/are + S + V-ing?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-009','present-continuous','A1',3,'Nhìn kìa! Con mèo đang ngủ trên ghế sofa.','Look! The cat is sleeping on the sofa.','["Look! The cat is sleeping on the couch."]','["look", "cat", "sleep", "on", "sofa"]','Look! báo hiệu việc đang xảy ra → V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-continuous-010','present-continuous','A1',3,'Họ đang đợi xe buýt.','They are waiting for the bus.',NULL,'["they", "wait", "for", "bus"]','They + are + V-ing; wait for + N.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-001','past-simple-be','A1',1,'Hôm qua tôi đã ở nhà.','I was at home yesterday.','["Yesterday I was at home.", "I was home yesterday.", "Yesterday I was home."]','["I", "be", "at", "home", "yesterday"]','Quá khứ của am/is → was.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-002','past-simple-be','A1',1,'Hôm qua trời lạnh.','It was cold yesterday.','["Yesterday it was cold."]','["it", "be", "cold", "yesterday"]','It + was (quá khứ).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-003','past-simple-be','A1',1,'Tuần trước chúng tôi ở bãi biển.','We were at the beach last week.','["Last week we were at the beach."]','["we", "be", "at", "beach", "last week"]','We/you/they → were.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-004','past-simple-be','A1',1,'Tối qua cô ấy rất mệt.','She was very tired last night.','["Last night she was very tired."]','["she", "be", "very", "tired", "last night"]','She → was.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-005','past-simple-be','A1',2,'Hôm qua anh ấy không có ở trường.','He wasn''t at school yesterday.','["Yesterday he wasn''t at school."]','["he", "be", "not", "at", "school", "yesterday"]','Phủ định: wasn''t = was not.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-006','past-simple-be','A1',2,'Hôm qua những cửa hàng không mở cửa.','The shops weren''t open yesterday.','["Yesterday the shops weren''t open.", "The stores weren''t open yesterday.", "Yesterday the stores weren''t open."]','["shop", "be", "not", "open", "yesterday"]','Chủ ngữ số nhiều → weren''t.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-007','past-simple-be','A1',2,'Hôm qua bạn có bị ốm không?','Were you ill yesterday?','["Were you sick yesterday?"]','["you", "be", "ill", "yesterday"]','Câu hỏi: Were + you + ...?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-008','past-simple-be','A1',2,'Năm ngoái thầy giáo của bạn là ai?','Who was your teacher last year?',NULL,'["who", "be", "your", "teacher", "last year"]','Wh- + was + ...?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-009','past-simple-be','A1',3,'Khi còn nhỏ, tôi rất nhút nhát.','When I was little, I was very shy.','["When I was young, I was very shy.", "When I was a child, I was very shy.", "When I was small, I was very shy.", "I was very shy when I was little.", "I was very shy when I was young.", "I was very shy when I was a child."]','["when", "I", "be", "little", "very", "shy"]','Cả hai mệnh đề đều ở quá khứ → was.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-be-010','past-simple-be','A1',3,'Tối qua bố mẹ tôi không ở nhà.','My parents weren''t at home last night.','["Last night my parents weren''t at home.", "My parents weren''t home last night.", "Last night my parents weren''t home."]','["my", "parent", "be", "not", "at", "home", "last night"]','My parents (số nhiều) → weren''t.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-001','prepositions-time','A1',1,'Tôi sinh vào tháng Năm.','I was born in May.',NULL,'["I", "be", "born", "in", "May"]','Tháng → in.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-002','prepositions-time','A1',1,'Thứ Hai tôi có tiết toán.','I have maths on Monday.','["I have math on Monday.", "On Monday I have maths.", "On Monday I have math.", "I have maths on Mondays.", "I have math on Mondays."]','["I", "have", "maths", "on", "Monday"]','Thứ trong tuần → on.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-003','prepositions-time','A1',1,'Bộ phim bắt đầu lúc bảy giờ.','The film starts at seven o''clock.','["The movie starts at seven o''clock.", "The film starts at 7 o''clock.", "The movie starts at 7 o''clock.", "The film starts at seven.", "The movie starts at seven."]','["film", "start", "at", "seven o''clock"]','Giờ → at.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-004','prepositions-time','A1',1,'Chúng tôi đi bơi vào mùa hè.','We go swimming in summer.','["In summer we go swimming."]','["we", "go", "swim", "in", "summer"]','Mùa → in.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-005','prepositions-time','A1',2,'Tôi đọc sách vào buổi tối.','I read books in the evening.','["I read in the evening.", "In the evening I read books.", "In the evening I read."]','["I", "read", "book", "in the evening"]','Buổi trong ngày → in the morning/afternoon/evening.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-006','prepositions-time','A1',2,'Sinh nhật cô ấy vào thứ Bảy.','Her birthday is on Saturday.',NULL,'["her", "birthday", "be", "on", "Saturday"]','Thứ trong tuần → on.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-007','prepositions-time','A1',2,'Chúng tôi không đi học vào cuối tuần.','We don''t go to school at the weekend.','["We don''t go to school on the weekend.", "We don''t go to school at weekends.", "We don''t go to school on weekends."]','["we", "go", "school", "at", "weekend", "not"]','Cuối tuần: at the weekend (Anh) / on the weekend (Mỹ).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-008','prepositions-time','A1',2,'Bạn có dậy sớm vào buổi sáng không?','Do you get up early in the morning?','["Do you wake up early in the morning?"]','["you", "get up", "early", "in the morning"]','Buổi sáng → in the morning.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-009','prepositions-time','A1',3,'Bố tôi đi ngủ lúc nửa đêm.','My father goes to bed at midnight.','["My dad goes to bed at midnight."]','["my", "father", "go", "bed", "at", "midnight"]','Thời điểm cụ thể (midnight, noon, night) → at.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-time-010','prepositions-time','A1',3,'Trường tôi đóng cửa vào ngày Giáng sinh.','My school is closed on Christmas Day.','["My school closes on Christmas Day."]','["my", "school", "be", "closed", "on", "Christmas Day"]','Một ngày cụ thể → on.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-001','prepositions-place','A1',1,'Con mèo ở trên bàn.','The cat is on the table.',NULL,'["cat", "be", "on", "table"]','Trên bề mặt → on.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-002','prepositions-place','A1',1,'Quả bóng ở dưới ghế.','The ball is under the chair.',NULL,'["ball", "be", "under", "chair"]','Bên dưới → under.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-003','prepositions-place','A1',1,'Chiếc điện thoại ở trong cặp của tôi.','The phone is in my bag.','["The phone is in my schoolbag."]','["phone", "be", "in", "my", "bag"]','Bên trong → in.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-004','prepositions-place','A1',1,'Ngân hàng ở bên cạnh bưu điện.','The bank is next to the post office.','["The bank is beside the post office."]','["bank", "be", "next to", "post office"]','Bên cạnh → next to / beside.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-005','prepositions-place','A1',2,'Chiếc ô tô ở phía sau ngôi nhà.','The car is behind the house.',NULL,'["car", "be", "behind", "house"]','Phía sau → behind.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-006','prepositions-place','A1',2,'Có một công viên đối diện trường tôi.','There is a park opposite my school.','["There is a park across from my school."]','["there", "be", "park", "opposite", "my", "school"]','Đối diện → opposite / across from.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-007','prepositions-place','A1',2,'Bố tôi đang ở chỗ làm.','My father is at work.','["My dad is at work."]','["my", "father", "be", "at", "work"]','Ở một địa điểm/nơi làm việc → at (at work, at school).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-008','prepositions-place','A1',2,'Cửa hàng ở giữa ngân hàng và quán cà phê.','The shop is between the bank and the cafe.','["The shop is between the bank and the café.", "The store is between the bank and the cafe.", "The store is between the bank and the café."]','["shop", "be", "between", "bank", "and", "cafe"]','Ở giữa hai vật → between ... and ...',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-009','prepositions-place','A1',3,'Bức tranh ở phía trên giường.','The picture is above the bed.','["The picture is over the bed.", "The painting is above the bed.", "The painting is over the bed."]','["picture", "be", "above", "bed"]','Phía trên (không chạm) → above.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-prepositions-place-010','prepositions-place','A1',3,'Ô tô của anh ấy ở trước nhà tôi.','His car is in front of my house.',NULL,'["his", "car", "be", "in front of", "my", "house"]','Phía trước → in front of.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-001','adverbs-of-frequency','A1',1,'Tôi luôn đánh răng trước khi đi ngủ.','I always brush my teeth before bed.','["I always brush my teeth before I go to bed.", "I always brush my teeth before going to bed."]','["I", "always", "brush", "my", "tooth", "before", "bed"]','Trạng từ tần suất đứng TRƯỚC động từ thường.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-002','adverbs-of-frequency','A1',1,'Cô ấy thường đi bộ đến trường.','She usually walks to school.','["She often walks to school."]','["she", "usually", "walk", "to", "school"]','usually đứng trước động từ; she → walks.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-003','adverbs-of-frequency','A1',1,'Anh ấy không bao giờ ăn thịt.','He never eats meat.',NULL,'["he", "never", "eat", "meat"]','never đã mang nghĩa phủ định, không thêm doesn''t.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-004','adverbs-of-frequency','A1',1,'Chúng tôi thỉnh thoảng đi xem phim.','We sometimes go to the cinema.','["We sometimes go to the movies.", "Sometimes we go to the cinema.", "Sometimes we go to the movies."]','["we", "sometimes", "go", "cinema"]','sometimes có thể đứng trước động từ hoặc đầu câu.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-005','adverbs-of-frequency','A1',2,'Tôi hiếm khi uống nước ngọt.','I rarely drink soft drinks.','["I seldom drink soft drinks.", "I hardly ever drink soft drinks.", "I rarely drink soda.", "I seldom drink soda.", "I hardly ever drink soda."]','["I", "rarely", "drink", "soft drink"]','rarely/seldom đứng trước động từ thường.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-006','adverbs-of-frequency','A1',2,'Cô ấy luôn đúng giờ.','She is always on time.','["She is always punctual."]','["she", "be", "always", "on time"]','Trạng từ tần suất đứng SAU động từ to be.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-007','adverbs-of-frequency','A1',2,'Họ thường xuyên đến muộn.','They are often late.',NULL,'["they", "be", "often", "late"]','Sau to be: are often.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-008','adverbs-of-frequency','A1',2,'Bạn có thường chơi thể thao không?','Do you often play sports?','["Do you often play sport?", "Do you usually play sports?", "Do you usually play sport?"]','["you", "often", "play", "sport"]','Câu hỏi: Do + S + often + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-009','adverbs-of-frequency','A1',3,'Bố tôi không bao giờ đi làm muộn.','My father is never late for work.','["My dad is never late for work."]','["my", "father", "be", "never", "late", "for", "work"]','never đứng sau to be: is never late.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-adverbs-of-frequency-010','adverbs-of-frequency','A1',3,'Vào cuối tuần chúng tôi thường thăm ông bà.','We usually visit our grandparents at the weekend.','["At the weekend we usually visit our grandparents.", "We usually visit our grandparents on the weekend.", "On the weekend we usually visit our grandparents.", "We often visit our grandparents at the weekend.", "We often visit our grandparents on the weekend."]','["we", "usually", "visit", "our", "grandparent", "at", "weekend"]','usually đứng trước động từ thường (visit).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-001','some-any','A1',1,'Tôi có vài quyển sách.','I have some books.',NULL,'["I", "have", "some", "book"]','Câu khẳng định → some.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-002','some-any','A1',1,'Có một ít sữa trong tủ lạnh.','There is some milk in the fridge.',NULL,'["there", "be", "some", "milk", "in", "fridge"]','Câu khẳng định, danh từ không đếm được → some.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-003','some-any','A1',1,'Tôi không có cây bút chì nào.','I don''t have any pencils.','["I haven''t got any pencils."]','["I", "have", "any", "pencil", "not"]','Câu phủ định → any.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-004','some-any','A1',1,'Không có quả trứng nào trong bếp.','There aren''t any eggs in the kitchen.','["There are no eggs in the kitchen."]','["there", "be", "any", "egg", "in", "kitchen", "not"]','Câu phủ định → any (hoặc no).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-005','some-any','A1',2,'Bạn có anh chị em nào không?','Do you have any brothers or sisters?','["Do you have any siblings?", "Have you got any brothers or sisters?"]','["you", "have", "any", "brother", "sister"]','Câu hỏi → any.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-006','some-any','A1',2,'Bạn có muốn uống chút nước không?','Would you like some water?',NULL,'["would", "you", "like", "some", "water"]','Lời mời dùng some dù là câu hỏi.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-007','some-any','A1',2,'Mẹ tôi cần một ít gạo.','My mother needs some rice.','["My mum needs some rice.", "My mom needs some rice."]','["my", "mother", "need", "some", "rice"]','Câu khẳng định → some.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-008','some-any','A1',2,'Có đứa trẻ nào trong công viên không?','Are there any children in the park?','["Are there any kids in the park?"]','["there", "be", "any", "child", "in", "park"]','Câu hỏi → any.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-009','some-any','A1',3,'Anh ấy không uống chút trà nào.','He doesn''t drink any tea.',NULL,'["he", "drink", "any", "tea", "not"]','Câu phủ định → any.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-some-any-010','some-any','A1',3,'Tôi có thể mượn vài cái bút không?','Can I borrow some pens?','["Could I borrow some pens?"]','["can", "I", "borrow", "some", "pen"]','Lời đề nghị/xin phép dùng some.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-001','comparative-adjectives','A1',1,'Con voi to hơn con chó.','The elephant is bigger than the dog.','["Elephants are bigger than dogs."]','["elephant", "be", "big", "than", "dog"]','Tính từ ngắn: big → bigger (gấp đôi phụ âm) + than.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-002','comparative-adjectives','A1',1,'Anh trai tôi cao hơn tôi.','My brother is taller than me.','["My brother is taller than I am.", "My brother is taller than I."]','["my", "brother", "be", "tall", "than", "me"]','Tính từ ngắn + -er + than.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-003','comparative-adjectives','A1',1,'Mùa hè nóng hơn mùa xuân.','Summer is hotter than spring.',NULL,'["summer", "be", "hot", "than", "spring"]','hot → hotter (gấp đôi t).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-004','comparative-adjectives','A1',1,'Quyển sách này thú vị hơn quyển sách kia.','This book is more interesting than that book.','["This book is more interesting than that one."]','["this", "book", "be", "interesting", "than", "that"]','Tính từ dài: more + adj + than.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-005','comparative-adjectives','A1',2,'Bài tập này dễ hơn bài kia.','This exercise is easier than that one.','["This exercise is easier than that exercise."]','["this", "exercise", "be", "easy", "than", "that", "one"]','Tận cùng -y: easy → easier.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-006','comparative-adjectives','A1',2,'Xe đạp của tôi rẻ hơn xe đạp của bạn.','My bike is cheaper than your bike.','["My bike is cheaper than yours.", "My bicycle is cheaper than yours.", "My bicycle is cheaper than your bicycle."]','["my", "bike", "be", "cheap", "than", "your"]','cheap → cheaper.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-007','comparative-adjectives','A1',2,'Con mèo của tôi béo hơn con mèo của cô ấy.','My cat is fatter than her cat.','["My cat is fatter than hers."]','["my", "cat", "be", "fat", "than", "her"]','fat → fatter (gấp đôi t).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-008','comparative-adjectives','A1',2,'Bà tôi già hơn ông tôi.','My grandmother is older than my grandfather.','["My grandma is older than my grandpa.", "My grandmother is older than my grandpa.", "My grandma is older than my grandfather."]','["my", "grandmother", "be", "old", "than", "grandfather"]','old → older.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-009','comparative-adjectives','A1',3,'Môn toán có khó hơn tiếng Anh không?','Is maths more difficult than English?','["Is math more difficult than English?", "Is maths harder than English?", "Is math harder than English?"]','["maths", "be", "difficult", "than", "English"]','Tính từ dài: more difficult (hoặc harder).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparative-adjectives-010','comparative-adjectives','A1',3,'Phòng của tôi không sạch hơn phòng của bạn.','My room isn''t cleaner than your room.','["My room isn''t cleaner than yours."]','["my", "room", "be", "clean", "than", "your", "not"]','clean → cleaner; phủ định ở động từ to be.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-001','question-words','A1',1,'Bạn tên là gì?','What is your name?',NULL,'["what", "your", "name", "be"]','Hỏi cái gì → What.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-002','question-words','A1',1,'Bạn sống ở đâu?','Where do you live?',NULL,'["where", "you", "live"]','Hỏi nơi chốn → Where + do + S + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-003','question-words','A1',1,'Sinh nhật của bạn là khi nào?','When is your birthday?',NULL,'["when", "your", "birthday", "be"]','Hỏi thời gian → When.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-004','question-words','A1',1,'Ai là giáo viên tiếng Anh của bạn?','Who is your English teacher?',NULL,'["who", "your", "English", "teacher", "be"]','Hỏi người → Who.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-005','question-words','A1',2,'Tại sao bạn buồn?','Why are you sad?',NULL,'["why", "you", "be", "sad"]','Hỏi lý do → Why.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-006','question-words','A1',2,'Bạn đi học bằng cách nào?','How do you go to school?','["How do you get to school?"]','["how", "you", "go", "school"]','Hỏi cách thức → How.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-007','question-words','A1',2,'Bạn bao nhiêu tuổi?','How old are you?',NULL,'["how", "old", "you", "be"]','Hỏi tuổi → How old.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-008','question-words','A1',2,'Bạn thích màu gì?','What colour do you like?','["What color do you like?", "Which colour do you like?", "Which color do you like?"]','["what", "colour", "you", "like"]','What + danh từ + do + S + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-009','question-words','A1',3,'Cô ấy làm việc ở đâu?','Where does she work?',NULL,'["where", "she", "work"]','Where + does + she + V nguyên thể?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-question-words-010','question-words','A1',3,'Đây là cặp sách của ai?','Whose bag is this?','["Whose schoolbag is this?", "Whose school bag is this?"]','["whose", "bag", "this", "be"]','Hỏi của ai → Whose + N.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-001','much-many','A1',1,'Bạn có bao nhiêu cái bút?','How many pens do you have?','["How many pens have you got?"]','["how", "many", "pen", "you", "have"]','Danh từ đếm được → How many + N số nhiều.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-002','much-many','A1',1,'Bạn cần bao nhiêu tiền?','How much money do you need?',NULL,'["how", "much", "money", "you", "need"]','Danh từ không đếm được (money) → How much.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-003','much-many','A1',1,'Tôi không có nhiều thời gian.','I don''t have much time.','["I haven''t got much time."]','["I", "have", "much", "time", "not"]','time không đếm được → much.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-004','much-many','A1',1,'Có nhiều học sinh trong sân trường.','There are many students in the schoolyard.','["There are many students in the school yard.", "There are a lot of students in the schoolyard.", "There are lots of students in the schoolyard."]','["there", "be", "many", "student", "in", "schoolyard"]','Danh từ đếm được số nhiều → many.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-005','much-many','A1',2,'Chiếc áo phông này giá bao nhiêu?','How much is this T-shirt?','["How much does this T-shirt cost?"]','["how", "much", "this", "T-shirt", "be"]','Hỏi giá → How much.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-006','much-many','A1',2,'Cô ấy không uống nhiều nước.','She doesn''t drink much water.',NULL,'["she", "drink", "much", "water", "not"]','water không đếm được → much.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-007','much-many','A1',2,'Có bao nhiêu người trong gia đình bạn?','How many people are there in your family?','["How many people are in your family?"]','["how", "many", "person", "there", "be", "in", "your", "family"]','people đếm được → How many.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-008','much-many','A1',2,'Bạn uống bao nhiêu sữa mỗi ngày?','How much milk do you drink every day?','["How much milk do you drink a day?", "How much milk do you drink each day?"]','["how", "much", "milk", "you", "drink", "every day"]','milk không đếm được → How much.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-009','much-many','A1',3,'Anh ấy không có nhiều bạn.','He doesn''t have many friends.','["He hasn''t got many friends."]','["he", "have", "many", "friend", "not"]','friends đếm được → many.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-much-many-010','much-many','A1',3,'Hôm nay chúng tôi không có nhiều bài tập về nhà.','We don''t have much homework today.','["Today we don''t have much homework.", "We haven''t got much homework today."]','["we", "have", "much", "homework", "today", "not"]','homework không đếm được → much.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-001','past-simple','A2',1,'Hôm qua tôi đã đi học bằng xe đạp.','I went to school by bike yesterday.','["Yesterday I went to school by bike.", "I went to school by bicycle yesterday.", "Yesterday I went to school by bicycle."]','["I", "go", "school", "bike", "yesterday"]','Động từ bất quy tắc: go → went (vì có yesterday).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-002','past-simple','A2',1,'Tuần trước chúng tôi đã thăm ông bà.','We visited our grandparents last week.','["Last week we visited our grandparents."]','["we", "visit", "our", "grandparent", "last week"]','Động từ có quy tắc thêm -ed: visit → visited.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-003','past-simple','A2',1,'Tối qua cô ấy đã xem một bộ phim hay.','She watched a good film last night.','["Last night she watched a good film.", "She watched a good movie last night.", "Last night she watched a good movie."]','["she", "watch", "good", "film", "last night"]','watch → watched (quá khứ, có last night).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-004','past-simple','A2',1,'Hôm qua anh ấy đã mua một chiếc áo sơ mi mới.','He bought a new shirt yesterday.','["Yesterday he bought a new shirt."]','["he", "buy", "new", "shirt", "yesterday"]','Bất quy tắc: buy → bought.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-005','past-simple','A2',2,'Hôm qua tôi đã không làm bài tập về nhà.','I didn''t do my homework yesterday.','["Yesterday I didn''t do my homework.", "I didn''t do homework yesterday.", "Yesterday I didn''t do homework."]','["I", "do", "my", "homework", "yesterday", "not"]','Phủ định: didn''t + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-006','past-simple','A2',2,'Hôm qua cô ấy đã không đến trường.','She didn''t go to school yesterday.','["Yesterday she didn''t go to school."]','["she", "go", "school", "yesterday", "not"]','Phủ định: didn''t + go (không phải went).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-007','past-simple','A2',2,'Tuần trước bạn có xem bộ phim đó không?','Did you watch that film last week?','["Did you watch that movie last week?", "Last week did you watch that film?", "Last week did you watch that movie?"]','["you", "watch", "that", "film", "last week"]','Câu hỏi: Did + S + V nguyên thể?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-008','past-simple','A2',2,'Hôm qua bạn đã đi đâu?','Where did you go yesterday?',NULL,'["where", "you", "go", "yesterday"]','Wh- + did + S + V nguyên thể?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-009','past-simple','A2',3,'Hai năm trước gia đình tôi đã chuyển đến Hà Nội.','My family moved to Hanoi two years ago.','["Two years ago my family moved to Hanoi.", "My family moved to Ha Noi two years ago.", "Two years ago my family moved to Ha Noi."]','["my", "family", "move", "to", "Hanoi", "two years ago"]','ago báo hiệu quá khứ đơn: move → moved.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-simple-010','past-simple','A2',3,'Năm ngoái anh trai tôi đã học bơi.','My brother learned to swim last year.','["Last year my brother learned to swim.", "My brother learnt to swim last year.", "Last year my brother learnt to swim."]','["my", "brother", "learn", "to", "swim", "last year"]','learn → learned/learnt (có last year).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-001','future-will','A2',1,'Tôi sẽ giúp bạn.','I will help you.',NULL,'["I", "will", "help", "you"]','will + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-002','future-will','A2',1,'Ngày mai trời sẽ mưa.','It will rain tomorrow.','["Tomorrow it will rain."]','["it", "will", "rain", "tomorrow"]','Dự đoán tương lai: will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-003','future-will','A2',1,'Tối nay cô ấy sẽ gọi cho bạn.','She will call you tonight.','["Tonight she will call you.", "She will phone you tonight.", "Tonight she will phone you."]','["she", "will", "call", "you", "tonight"]','will không đổi theo chủ ngữ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-004','future-will','A2',1,'Tôi nghĩ đội của chúng ta sẽ thắng.','I think our team will win.',NULL,'["I", "think", "our", "team", "will", "win"]','I think + S + will + V: dự đoán theo ý kiến.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-005','future-will','A2',2,'Tôi sẽ không nói với ai.','I won''t tell anyone.','["I won''t tell anybody."]','["I", "will", "tell", "anyone", "not"]','Phủ định: won''t = will not.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-006','future-will','A2',2,'Anh ấy sẽ không đến bữa tiệc.','He won''t come to the party.',NULL,'["he", "will", "come", "to", "party", "not"]','won''t + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-007','future-will','A2',2,'Bạn sẽ đến dự tiệc sinh nhật của tôi chứ?','Will you come to my birthday party?',NULL,'["you", "will", "come", "to", "my", "birthday party"]','Câu hỏi: Will + S + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-008','future-will','A2',2,'Năm sau tôi sẽ mười hai tuổi.','I will be twelve next year.','["Next year I will be twelve.", "I will be twelve years old next year.", "Next year I will be twelve years old.", "I will be 12 next year.", "Next year I will be 12."]','["I", "will", "be", "twelve", "next year"]','will + be (không bỏ be).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-009','future-will','A2',3,'Trời lạnh quá. Tôi sẽ đóng cửa sổ.','It''s very cold. I''ll close the window.','["It''s so cold. I''ll close the window.", "It''s really cold. I''ll close the window.", "It''s very cold. I''ll shut the window."]','["it", "be", "cold", "I", "will", "close", "window"]','Quyết định ngay lúc nói → will.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-will-010','future-will','A2',3,'Bạn nghĩ ai sẽ thắng trận đấu?','Who do you think will win the match?','["Who do you think will win the game?"]','["who", "you", "think", "will", "win", "match"]','Who do you think + will + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-001','future-going-to','A2',1,'Cuối tuần này tôi định đi thăm bà.','I''m going to visit my grandmother this weekend.','["This weekend I''m going to visit my grandmother.", "I''m going to visit my grandma this weekend.", "This weekend I''m going to visit my grandma."]','["I", "be", "going to", "visit", "my", "grandmother", "this weekend"]','Dự định đã có từ trước → be going to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-002','future-going-to','A2',1,'Chúng tôi định mua một chiếc ô tô mới.','We are going to buy a new car.',NULL,'["we", "be", "going to", "buy", "new", "car"]','We + are going to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-003','future-going-to','A2',1,'Cô ấy định học tiếng Nhật.','She is going to learn Japanese.','["She is going to study Japanese."]','["she", "be", "going to", "learn", "Japanese"]','She + is going to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-004','future-going-to','A2',1,'Nhìn những đám mây kia kìa! Trời sắp mưa.','Look at those clouds! It''s going to rain.',NULL,'["look", "at", "those", "cloud", "it", "be", "going to", "rain"]','Dự đoán có dấu hiệu rõ ràng → be going to.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-005','future-going-to','A2',2,'Tối nay tôi không định ra ngoài.','I''m not going to go out tonight.','["Tonight I''m not going to go out.", "I''m not going out tonight."]','["I", "be", "going to", "go out", "tonight", "not"]','Phủ định: am/is/are + not + going to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-006','future-going-to','A2',2,'Họ không định tổ chức tiệc.','They aren''t going to have a party.','["They aren''t going to throw a party."]','["they", "be", "going to", "have", "party", "not"]','They + aren''t going to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-007','future-going-to','A2',2,'Bạn có định xem trận đấu không?','Are you going to watch the match?','["Are you going to watch the game?"]','["you", "be", "going to", "watch", "match"]','Câu hỏi: Are + you + going to + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-008','future-going-to','A2',2,'Anh ấy định làm gì sau khi tốt nghiệp?','What is he going to do after he graduates?','["What is he going to do after graduation?", "What is he going to do after graduating?"]','["what", "he", "be", "going to", "do", "after", "graduate"]','Wh- + is + S + going to + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-009','future-going-to','A2',3,'Cẩn thận! Cậu bé sắp ngã.','Be careful! The boy is going to fall.','["Careful! The boy is going to fall.", "Watch out! The boy is going to fall."]','["careful", "boy", "be", "going to", "fall"]','Thấy rõ sắp xảy ra → be going to.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-future-going-to-010','future-going-to','A2',3,'Mùa hè này chúng tôi định đi cắm trại.','We are going to go camping this summer.','["This summer we are going to go camping.", "We are going camping this summer.", "This summer we are going camping."]','["we", "be", "going to", "go", "camp", "this summer"]','Kế hoạch đã định → be going to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-001','present-perfect','A2',1,'Tôi đã xem bộ phim này rồi.','I have already seen this film.','["I have seen this film already.", "I have already seen this movie.", "I have seen this movie already."]','["I", "have", "already", "see", "this", "film"]','have + V3 (see → seen); already = rồi.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-002','present-perfect','A2',1,'Cô ấy đã đến Nhật Bản hai lần.','She has been to Japan twice.','["She has visited Japan twice.", "She has been to Japan two times."]','["she", "have", "be", "to", "Japan", "twice"]','Kinh nghiệm (số lần) → has + been to.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-003','present-perfect','A2',1,'Chúng tôi đã sống ở đây được năm năm.','We have lived here for five years.','["We have been living here for five years."]','["we", "have", "live", "here", "for", "five years"]','Kéo dài đến hiện tại + for + khoảng thời gian.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-004','present-perfect','A2',1,'Tôi chưa bao giờ ăn sầu riêng.','I have never eaten durian.',NULL,'["I", "have", "never", "eat", "durian"]','have + never + V3 (eat → eaten).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-005','present-perfect','A2',2,'Anh ấy chưa làm xong bài tập về nhà.','He hasn''t finished his homework yet.','["He hasn''t finished his homework.", "He hasn''t done his homework yet.", "He hasn''t done his homework."]','["he", "have", "finish", "his", "homework", "yet", "not"]','Phủ định: hasn''t + V3 ... yet.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-006','present-perfect','A2',2,'Họ vẫn chưa gặp thầy giáo mới.','They haven''t met the new teacher yet.','["They still haven''t met the new teacher.", "They haven''t met the new teacher."]','["they", "have", "meet", "new", "teacher", "yet", "not"]','haven''t + V3 (meet → met).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-007','present-perfect','A2',2,'Bạn đã bao giờ đi máy bay chưa?','Have you ever travelled by plane?','["Have you ever traveled by plane?", "Have you ever been on a plane?", "Have you ever flown?", "Have you ever flown on a plane?"]','["you", "have", "ever", "travel", "by", "plane"]','Hỏi kinh nghiệm: Have + S + ever + V3?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-008','present-perfect','A2',2,'Bạn đã ăn trưa chưa?','Have you had lunch yet?','["Have you had lunch?", "Have you eaten lunch yet?", "Have you eaten lunch?"]','["you", "have", "lunch", "yet"]','đã ... chưa? → Have + S + V3 ... yet?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-009','present-perfect','A2',3,'Tôi đã biết cô ấy từ năm 2019.','I have known her since 2019.',NULL,'["I", "have", "know", "her", "since", "2019"]','Mốc bắt đầu → since; know → known.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-010','present-perfect','A2',3,'Bố tôi vừa mới về nhà.','My father has just come home.','["My dad has just come home.", "My father has just got home.", "My dad has just got home.", "My father has just gotten home.", "My dad has just gotten home.", "My father has just arrived home.", "My dad has just arrived home."]','["my", "father", "have", "just", "come", "home"]','Vừa mới → has + just + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-001','comparatives-superlatives','A2',1,'Đây là tòa nhà cao nhất trong thành phố.','This is the tallest building in the city.','["This is the highest building in the city."]','["this", "be", "tall", "building", "in", "city"]','So sánh nhất tính từ ngắn: the + adj-est.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-002','comparatives-superlatives','A2',1,'Cô ấy là học sinh giỏi nhất lớp tôi.','She is the best student in my class.','["She is the best pupil in my class."]','["she", "be", "good", "student", "in", "my", "class"]','Bất quy tắc: good → better → the best.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-003','comparatives-superlatives','A2',1,'Tháng Tám là tháng nóng nhất trong năm.','August is the hottest month of the year.','["August is the hottest month in the year."]','["August", "be", "hot", "month", "of", "year"]','hot → the hottest (gấp đôi t).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-004','comparatives-superlatives','A2',1,'Xe buýt chậm hơn tàu hỏa.','The bus is slower than the train.','["Buses are slower than trains."]','["bus", "be", "slow", "than", "train"]','So sánh hơn: adj-er + than.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-005','comparatives-superlatives','A2',2,'Đây là ngày tồi tệ nhất trong đời tôi.','This is the worst day of my life.',NULL,'["this", "be", "bad", "day", "of", "my", "life"]','Bất quy tắc: bad → worse → the worst.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-006','comparatives-superlatives','A2',2,'Tiếng Anh dễ hơn tiếng Trung.','English is easier than Chinese.',NULL,'["English", "be", "easy", "than", "Chinese"]','easy → easier (y → i + er).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-007','comparatives-superlatives','A2',2,'Bài kiểm tra này khó hơn bài lần trước nhiều.','This test is much harder than the last one.','["This test is much more difficult than the last one.", "This test is much harder than the previous one.", "This test is much more difficult than the previous one."]','["this", "test", "be", "much", "hard", "than", "last", "one"]','much + so sánh hơn để nhấn mạnh.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-008','comparatives-superlatives','A2',2,'Ai là người cao nhất trong gia đình bạn?','Who is the tallest person in your family?','["Who is the tallest in your family?"]','["who", "be", "tall", "person", "in", "your", "family"]','the + adj-est + in + nhóm/nơi chốn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-009','comparatives-superlatives','A2',3,'Điện thoại của tôi không đắt hơn điện thoại của bạn.','My phone isn''t more expensive than yours.','["My phone isn''t more expensive than your phone."]','["my", "phone", "be", "expensive", "than", "your", "not"]','Tính từ dài: more + adj + than.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-comparatives-superlatives-010','comparatives-superlatives','A2',3,'Đây là bộ phim thú vị nhất mà tôi từng xem.','This is the most interesting film I have ever seen.','["This is the most interesting film that I have ever seen.", "This is the most interesting movie I have ever seen.", "This is the most interesting movie that I have ever seen."]','["this", "be", "interesting", "film", "I", "have", "ever", "see"]','Tính từ dài: the most + adj; thường đi với have ever + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-001','countable-uncountable','A2',1,'Tôi cần một ít đường.','I need some sugar.',NULL,'["I", "need", "some", "sugar"]','sugar không đếm được: không dùng a, không thêm -s.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-002','countable-uncountable','A2',1,'Có rất nhiều đồ đạc trong phòng.','There is a lot of furniture in the room.','["There is lots of furniture in the room."]','["there", "be", "a lot of", "furniture", "in", "room"]','furniture không đếm được → is, không thêm -s.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-003','countable-uncountable','A2',1,'Hôm qua cô ấy đã cho tôi một lời khuyên hay.','She gave me a good piece of advice yesterday.','["Yesterday she gave me a good piece of advice.", "She gave me some good advice yesterday.", "Yesterday she gave me some good advice.", "She gave me good advice yesterday."]','["she", "give", "me", "good", "piece", "of", "advice", "yesterday"]','advice không đếm được → a piece of advice.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-004','countable-uncountable','A2',1,'Tóc của cô ấy rất dài.','Her hair is very long.',NULL,'["her", "hair", "be", "very", "long"]','hair (tóc nói chung) không đếm được → is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-005','countable-uncountable','A2',2,'Chúng tôi có rất ít thông tin.','We have very little information.',NULL,'["we", "have", "very", "little", "information"]','information không đếm được → little (không dùng few).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-006','countable-uncountable','A2',2,'Hành lý của bạn ở đâu?','Where is your luggage?','["Where is your baggage?"]','["where", "be", "your", "luggage"]','luggage không đếm được → is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-007','countable-uncountable','A2',2,'Tôi muốn mua hai ổ bánh mì.','I want to buy two loaves of bread.',NULL,'["I", "want", "buy", "two", "loaf", "of", "bread"]','bread không đếm được → đếm bằng loaf (loaves).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-008','countable-uncountable','A2',2,'Có bao nhiêu sữa trong chai?','How much milk is there in the bottle?','["How much milk is in the bottle?"]','["how", "much", "milk", "there", "be", "in", "bottle"]','milk không đếm được → How much + is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-009','countable-uncountable','A2',3,'Tin tức hôm nay rất tốt.','Today''s news is very good.','["The news is very good today.", "Today the news is very good."]','["today", "news", "be", "very", "good"]','news không đếm được, dù có -s → is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-countable-uncountable-010','countable-uncountable','A2',3,'Bạn có thể cho tôi một cốc nước được không?','Can you give me a glass of water?','["Could you give me a glass of water?", "Can you give me a cup of water?", "Could you give me a cup of water?"]','["can", "you", "give", "me", "glass", "of", "water"]','water không đếm được → a glass of water.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-001','first-conditional','A2',1,'Nếu trời mưa, tôi sẽ ở nhà.','If it rains, I will stay at home.','["If it rains, I will stay home.", "I will stay at home if it rains.", "I will stay home if it rains."]','["if", "it", "rain", "I", "will", "stay", "at", "home"]','If + hiện tại đơn, will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-002','first-conditional','A2',1,'Nếu bạn học chăm, bạn sẽ đỗ kỳ thi.','If you study hard, you will pass the exam.','["You will pass the exam if you study hard."]','["if", "you", "study", "hard", "will", "pass", "exam"]','Mệnh đề If dùng hiện tại đơn, không dùng will.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-003','first-conditional','A2',1,'Nếu cô ấy đến muộn, cô ấy sẽ lỡ xe buýt.','If she is late, she will miss the bus.','["If she comes late, she will miss the bus.", "She will miss the bus if she is late.", "She will miss the bus if she comes late."]','["if", "she", "be", "late", "will", "miss", "bus"]','If + she is/comes (hiện tại đơn), she will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-004','first-conditional','A2',1,'Nếu bạn không ăn sáng, bạn sẽ bị đói.','If you don''t have breakfast, you will be hungry.','["If you don''t eat breakfast, you will be hungry.", "You will be hungry if you don''t have breakfast.", "You will be hungry if you don''t eat breakfast."]','["if", "you", "have", "breakfast", "not", "will", "be", "hungry"]','If + don''t + V, will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-005','first-conditional','A2',2,'Nếu trời không mưa, chúng tôi sẽ đi dã ngoại.','If it doesn''t rain, we will go on a picnic.','["If it doesn''t rain, we will have a picnic.", "We will go on a picnic if it doesn''t rain.", "We will have a picnic if it doesn''t rain."]','["if", "it", "rain", "not", "we", "will", "go", "picnic"]','If + it doesn''t + V, will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-006','first-conditional','A2',2,'Tôi sẽ gọi cho bạn nếu tôi có thời gian.','I will call you if I have time.','["I will phone you if I have time.", "If I have time, I will call you.", "If I have time, I will phone you."]','["I", "will", "call", "you", "if", "have", "time"]','Mệnh đề will có thể đứng trước if (không cần dấu phẩy).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-007','first-conditional','A2',2,'Nếu bạn nhấn nút này, máy sẽ dừng lại.','If you press this button, the machine will stop.','["The machine will stop if you press this button."]','["if", "you", "press", "this", "button", "machine", "will", "stop"]','If + hiện tại đơn, will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-008','first-conditional','A2',2,'Bạn sẽ làm gì nếu bạn trượt kỳ thi?','What will you do if you fail the exam?','["If you fail the exam, what will you do?"]','["what", "will", "you", "do", "if", "fail", "exam"]','Câu hỏi: Wh- + will + S + V + if + hiện tại đơn?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-009','first-conditional','A2',3,'Nếu anh ấy không nhanh lên, anh ấy sẽ bị muộn học.','If he doesn''t hurry, he will be late for school.','["If he doesn''t hurry up, he will be late for school.", "He will be late for school if he doesn''t hurry.", "He will be late for school if he doesn''t hurry up."]','["if", "he", "hurry", "not", "will", "be", "late", "for", "school"]','If + he doesn''t + V, he will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-first-conditional-010','first-conditional','A2',3,'Nếu bạn để kem ngoài nắng, nó sẽ tan chảy.','If you leave the ice cream in the sun, it will melt.','["The ice cream will melt if you leave it in the sun."]','["if", "you", "leave", "ice cream", "in", "sun", "it", "will", "melt"]','If + hiện tại đơn, will + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-001','have-to','A2',1,'Tôi phải mặc đồng phục ở trường.','I have to wear a uniform at school.','["At school I have to wear a uniform."]','["I", "have to", "wear", "uniform", "at", "school"]','Bắt buộc: have to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-002','have-to','A2',1,'Cô ấy phải làm bài tập về nhà mỗi tối.','She has to do her homework every evening.','["She has to do homework every evening.", "She has to do her homework every night.", "She has to do homework every night.", "Every evening she has to do her homework."]','["she", "have to", "do", "her", "homework", "every evening"]','She/he → has to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-003','have-to','A2',1,'Anh ấy phải đi làm bằng xe buýt.','He has to go to work by bus.','["He has to take the bus to work."]','["he", "have to", "go", "work", "by", "bus"]','He → has to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-004','have-to','A2',1,'Chúng tôi không phải đi học vào Chủ nhật.','We don''t have to go to school on Sundays.','["We don''t have to go to school on Sunday.", "On Sundays we don''t have to go to school.", "On Sunday we don''t have to go to school."]','["we", "have to", "go", "school", "on", "Sunday", "not"]','Không bắt buộc → don''t have to.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-005','have-to','A2',2,'Bạn không cần phải mang theo đồ ăn.','You don''t have to bring food.','["You don''t have to bring any food."]','["you", "have to", "bring", "food", "not"]','don''t have to = không cần (không phải là cấm).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-006','have-to','A2',2,'Cô ấy không phải nấu ăn vì mẹ cô ấy nấu.','She doesn''t have to cook because her mother cooks.','["She doesn''t have to cook because her mum cooks.", "She doesn''t have to cook because her mom cooks."]','["she", "have to", "cook", "not", "because", "her", "mother"]','She → doesn''t have to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-007','have-to','A2',2,'Bạn có phải làm việc vào thứ Bảy không?','Do you have to work on Saturdays?','["Do you have to work on Saturday?"]','["you", "have to", "work", "on", "Saturday"]','Câu hỏi: Do + S + have to + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-008','have-to','A2',2,'Anh ấy có phải đeo kính không?','Does he have to wear glasses?',NULL,'["he", "have to", "wear", "glasses"]','Câu hỏi: Does + he + have to + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-009','have-to','A2',3,'Hôm qua tôi đã phải đợi xe buýt rất lâu.','I had to wait for the bus for a long time yesterday.','["Yesterday I had to wait for the bus for a long time.", "I had to wait a long time for the bus yesterday.", "Yesterday I had to wait a long time for the bus."]','["I", "have to", "wait", "for", "bus", "long time", "yesterday"]','Quá khứ của have to → had to.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-have-to-010','have-to','A2',3,'Ở Việt Nam, người ta phải lái xe bên phải.','In Vietnam, people have to drive on the right.','["People have to drive on the right in Vietnam.", "In Viet Nam, people have to drive on the right.", "People have to drive on the right in Viet Nam."]','["in", "Vietnam", "person", "have to", "drive", "on", "right"]','Quy định chung → have to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-001','should','A2',1,'Bạn nên đi ngủ sớm.','You should go to bed early.',NULL,'["you", "should", "go", "bed", "early"]','Lời khuyên: should + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-002','should','A2',1,'Anh ấy nên đi khám bác sĩ.','He should see a doctor.','["He should go to the doctor.", "He should go to a doctor."]','["he", "should", "see", "doctor"]','should không thêm -s với he.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-003','should','A2',1,'Chúng ta nên uống nhiều nước.','We should drink a lot of water.','["We should drink lots of water.", "We should drink plenty of water."]','["we", "should", "drink", "a lot of", "water"]','should + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-004','should','A2',1,'Bạn không nên ăn quá nhiều kẹo.','You shouldn''t eat too many sweets.','["You shouldn''t eat too much candy.", "You shouldn''t eat too many candies."]','["you", "should", "eat", "too", "many", "sweet", "not"]','Phủ định: shouldn''t + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-005','should','A2',2,'Trẻ em không nên xem tivi quá nhiều.','Children shouldn''t watch too much TV.','["Kids shouldn''t watch too much TV.", "Children shouldn''t watch too much television.", "Kids shouldn''t watch too much television."]','["child", "should", "watch", "too", "much", "TV", "not"]','shouldn''t + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-006','should','A2',2,'Cô ấy không nên ra ngoài một mình vào ban đêm.','She shouldn''t go out alone at night.','["She shouldn''t go out on her own at night.", "She shouldn''t go out by herself at night."]','["she", "should", "go out", "alone", "at night", "not"]','shouldn''t + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-007','should','A2',2,'Tôi có nên mang theo ô không?','Should I bring an umbrella?','["Should I take an umbrella?"]','["I", "should", "bring", "umbrella"]','Câu hỏi: Should + S + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-008','should','A2',2,'Bây giờ chúng ta nên làm gì?','What should we do now?',NULL,'["what", "should", "we", "do", "now"]','Wh- + should + S + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-009','should','A2',3,'Bạn nên học từ mới mỗi ngày.','You should learn new words every day.','["You should study new words every day.", "Every day you should learn new words."]','["you", "should", "learn", "new", "word", "every day"]','should + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-should-010','should','A2',3,'Tôi nghĩ bạn nên xin lỗi cô ấy.','I think you should apologise to her.','["I think you should apologize to her.", "I think you should say sorry to her."]','["I", "think", "you", "should", "apologise", "to", "her"]','I think + S + should + V: đưa lời khuyên nhẹ nhàng.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-001','may-might-possibility','A2',1,'Ngày mai trời có thể mưa.','It might rain tomorrow.','["It may rain tomorrow.", "Tomorrow it might rain.", "Tomorrow it may rain."]','["it", "might", "rain", "tomorrow"]','Khả năng không chắc chắn: might/may + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-002','may-might-possibility','A2',1,'Có lẽ cô ấy đang ở thư viện.','She might be in the library.','["She may be in the library.", "She might be at the library.", "She may be at the library."]','["she", "might", "be", "in", "library"]','might/may + be.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-003','may-might-possibility','A2',1,'Có lẽ tôi sẽ đi dự tiệc.','I might go to the party.','["I may go to the party."]','["I", "might", "go", "to", "party"]','might + V nguyên thể (không thêm will).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-004','may-might-possibility','A2',1,'Có lẽ anh ấy sẽ không đến.','He might not come.','["He may not come."]','["he", "might", "come", "not"]','Phủ định: might not + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-005','may-might-possibility','A2',2,'Có lẽ họ không biết câu trả lời.','They might not know the answer.','["They may not know the answer."]','["they", "might", "know", "answer", "not"]','might not + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-006','may-might-possibility','A2',2,'Cuối tuần này có lẽ chúng tôi sẽ đi biển.','We might go to the beach this weekend.','["We may go to the beach this weekend.", "This weekend we might go to the beach.", "This weekend we may go to the beach."]','["we", "might", "go", "beach", "this weekend"]','might + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-007','may-might-possibility','A2',2,'Cẩn thận, con chó đó có thể cắn bạn đấy.','Be careful, that dog might bite you.','["Be careful, that dog may bite you.", "Careful, that dog might bite you.", "Careful, that dog may bite you."]','["careful", "that", "dog", "might", "bite", "you"]','Khả năng có thể xảy ra → might/may.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-008','may-might-possibility','A2',2,'Tối nay có lẽ tôi sẽ không có thời gian.','I might not have time tonight.','["I may not have time tonight.", "Tonight I might not have time.", "Tonight I may not have time."]','["I", "might", "have", "time", "tonight", "not"]','might not + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-009','may-might-possibility','A2',3,'Có lẽ điện thoại của tôi ở trong ô tô.','My phone might be in the car.','["My phone may be in the car."]','["my", "phone", "might", "be", "in", "car"]','might + be + nơi chốn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-may-might-possibility-010','may-might-possibility','A2',3,'Năm sau có lẽ anh trai tôi sẽ đi du học.','My brother might study abroad next year.','["My brother may study abroad next year.", "Next year my brother might study abroad.", "Next year my brother may study abroad."]','["my", "brother", "might", "study", "abroad", "next year"]','might + V nguyên thể, không thêm -s.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-001','present-perfect-vs-past-simple','B1',1,'Tôi đã đến Nhật Bản vào năm 2019.','I went to Japan in 2019.','["In 2019 I went to Japan.", "I visited Japan in 2019.", "In 2019 I visited Japan."]','["I", "go", "to", "Japan", "in", "2019"]','Mốc thời gian quá khứ cụ thể (in 2019) → quá khứ đơn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-002','present-perfect-vs-past-simple','B1',1,'Tôi đã đến Nhật Bản ba lần rồi.','I have been to Japan three times.','["I have visited Japan three times."]','["I", "have", "be", "to", "Japan", "three times"]','Kinh nghiệm, không nói khi nào → hiện tại hoàn thành.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-003','present-perfect-vs-past-simple','B1',1,'Hôm qua cô ấy đã làm mất chìa khóa.','She lost her key yesterday.','["Yesterday she lost her key.", "She lost her keys yesterday.", "Yesterday she lost her keys."]','["she", "lose", "her", "key", "yesterday"]','Có yesterday → quá khứ đơn (lost).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-004','present-perfect-vs-past-simple','B1',1,'Tôi chưa từng gặp anh ấy.','I have never met him.',NULL,'["I", "have", "never", "meet", "him"]','Chưa từng (đến nay) → have never + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-005','present-perfect-vs-past-simple','B1',2,'Bạn đã xem bộ phim đó chưa?','Have you seen that film yet?','["Have you seen that film?", "Have you seen that movie yet?", "Have you seen that movie?", "Have you watched that film yet?", "Have you watched that movie yet?"]','["you", "have", "see", "that", "film", "yet"]','đã ... chưa? → Have + S + V3 ... yet?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-006','present-perfect-vs-past-simple','B1',2,'Bạn đã xem nó khi nào?','When did you see it?','["When did you watch it?"]','["when", "you", "see", "it"]','Hỏi When → luôn dùng quá khứ đơn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-007','present-perfect-vs-past-simple','B1',2,'Chúng tôi đã sống ở Hà Nội từ năm 2015.','We have lived in Hanoi since 2015.','["We have been living in Hanoi since 2015.", "We have lived in Ha Noi since 2015.", "We have been living in Ha Noi since 2015."]','["we", "have", "live", "in", "Hanoi", "since", "2015"]','since + mốc, vẫn còn đến nay → hiện tại hoàn thành.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-008','present-perfect-vs-past-simple','B1',2,'Năm ngoái ông tôi đã nghỉ hưu.','My grandfather retired last year.','["Last year my grandfather retired.", "My grandpa retired last year.", "Last year my grandpa retired."]','["my", "grandfather", "retire", "last year"]','last year → quá khứ đơn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-009','present-perfect-vs-past-simple','B1',3,'Tôi ăn sáng rồi, nên tôi không đói.','I have already had breakfast, so I''m not hungry.','["I have had breakfast already, so I''m not hungry.", "I have already eaten breakfast, so I''m not hungry.", "I have eaten breakfast already, so I''m not hungry."]','["I", "have", "already", "breakfast", "so", "be", "hungry", "not"]','Kết quả còn ở hiện tại (không đói) → hiện tại hoàn thành.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-present-perfect-vs-past-simple-010','present-perfect-vs-past-simple','B1',3,'Sáng nay tôi đã ăn sáng lúc bảy giờ.','I had breakfast at seven o''clock this morning.','["This morning I had breakfast at seven o''clock.", "I ate breakfast at seven o''clock this morning.", "This morning I ate breakfast at seven o''clock.", "I had breakfast at seven this morning.", "I had breakfast at 7 o''clock this morning."]','["I", "have", "breakfast", "at", "seven o''clock", "this morning"]','Giờ cụ thể trong quá khứ → quá khứ đơn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-001','past-perfect','B1',1,'Khi tôi đến, bộ phim đã bắt đầu rồi.','When I arrived, the film had already started.','["When I arrived, the movie had already started.", "The film had already started when I arrived.", "The movie had already started when I arrived.", "When I got there, the film had already started.", "When I got there, the movie had already started."]','["when", "I", "arrive", "film", "have", "already", "start"]','Việc xảy ra trước một việc khác trong quá khứ → had + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-002','past-perfect','B1',1,'Cô ấy đã ăn tối trước khi bố mẹ cô ấy về nhà.','She had eaten dinner before her parents came home.','["She had had dinner before her parents came home.", "She had eaten dinner before her parents got home.", "She had had dinner before her parents got home.", "Before her parents came home, she had eaten dinner.", "Before her parents came home, she had had dinner."]','["she", "have", "eat", "dinner", "before", "her", "parent", "come", "home"]','Việc trước → had + V3; việc sau → quá khứ đơn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-003','past-perfect','B1',1,'Trước chuyến đi đó, tôi chưa bao giờ nhìn thấy biển.','I had never seen the sea before that trip.','["Before that trip, I had never seen the sea."]','["I", "have", "never", "see", "sea", "before", "that", "trip"]','had never + V3: chưa từng tính đến một mốc quá khứ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-004','past-perfect','B1',1,'Khi chúng tôi đến ga, tàu đã rời đi.','When we got to the station, the train had left.','["When we got to the station, the train had already left.", "When we arrived at the station, the train had left.", "When we arrived at the station, the train had already left.", "The train had left when we got to the station.", "The train had left when we arrived at the station."]','["when", "we", "get", "to", "station", "train", "have", "leave"]','Tàu đi trước khi chúng tôi đến → had left.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-005','past-perfect','B1',2,'Anh ấy đã không học bài, nên anh ấy trượt kỳ thi.','He hadn''t studied, so he failed the exam.','["He failed the exam because he hadn''t studied."]','["he", "have", "study", "not", "so", "fail", "exam"]','Nguyên nhân xảy ra trước → hadn''t + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-006','past-perfect','B1',2,'Cô ấy buồn vì cô ấy đã làm mất điện thoại.','She was sad because she had lost her phone.',NULL,'["she", "be", "sad", "because", "have", "lose", "her", "phone"]','Việc làm mất xảy ra trước khi buồn → had lost.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-007','past-perfect','B1',2,'Bạn đã làm xong bài tập về nhà trước khi cô giáo đến chưa?','Had you finished your homework before the teacher came?','["Had you finished your homework before the teacher arrived?", "Had you done your homework before the teacher came?", "Had you done your homework before the teacher arrived?"]','["you", "have", "finish", "your", "homework", "before", "teacher", "come"]','Câu hỏi: Had + S + V3 ... before + quá khứ đơn?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-008','past-perfect','B1',2,'Sau khi ăn sáng xong, chúng tôi đi học.','After we had eaten breakfast, we went to school.','["After we had had breakfast, we went to school.", "We went to school after we had eaten breakfast.", "We went to school after we had had breakfast."]','["after", "we", "have", "eat", "breakfast", "go", "school"]','After + had + V3, quá khứ đơn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-009','past-perfect','B1',3,'Tôi nhận ra rằng tôi đã để quên chìa khóa ở nhà.','I realised that I had left my keys at home.','["I realized that I had left my keys at home.", "I realised I had left my keys at home.", "I realized I had left my keys at home.", "I realised that I had left my key at home.", "I realized that I had left my key at home."]','["I", "realise", "that", "have", "leave", "my", "key", "at", "home"]','Việc để quên xảy ra trước khi nhận ra → had left.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-past-perfect-010','past-perfect','B1',3,'Trước năm 2020, họ chưa bao giờ đi máy bay.','Before 2020, they had never travelled by plane.','["Before 2020, they had never traveled by plane.", "They had never travelled by plane before 2020.", "They had never traveled by plane before 2020.", "Before 2020, they had never flown.", "They had never flown before 2020."]','["before", "2020", "they", "have", "never", "travel", "by", "plane"]','had never + V3 trước một mốc quá khứ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-001','second-conditional','B1',1,'Nếu tôi là bạn, tôi sẽ học chăm hơn.','If I were you, I would study harder.','["If I was you, I would study harder.", "I would study harder if I were you."]','["if", "I", "be", "you", "would", "study", "hard"]','Lời khuyên giả định: If I were you, I would + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-002','second-conditional','B1',1,'Nếu tôi là một con chim, tôi sẽ bay khắp thế giới.','If I were a bird, I would fly around the world.','["If I was a bird, I would fly around the world.", "If I were a bird, I would fly all over the world.", "I would fly around the world if I were a bird."]','["if", "I", "be", "bird", "would", "fly", "around", "world"]','Không có thật ở hiện tại: If + quá khứ (were), would + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-003','second-conditional','B1',1,'Giả sử tôi trúng xổ số, tôi sẽ mua một ngôi nhà cho bố mẹ.','If I won the lottery, I would buy a house for my parents.','["If I won the lottery, I would buy my parents a house.", "I would buy a house for my parents if I won the lottery.", "I would buy my parents a house if I won the lottery."]','["if", "I", "win", "lottery", "would", "buy", "house", "for", "my", "parent"]','If + quá khứ đơn (won), would + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-004','second-conditional','B1',1,'Tôi không có ô tô. Nếu có, tôi sẽ lái xe đi làm.','I don''t have a car. If I had one, I would drive to work.','["I don''t have a car. If I had a car, I would drive to work."]','["I", "have", "car", "not", "if", "one", "would", "drive", "to", "work"]','Trái với hiện tại → If + had, would + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-005','second-conditional','B1',2,'Anh ấy không biết bơi. Nếu biết bơi, anh ấy sẽ đi bơi cùng chúng tôi.','He can''t swim. If he could swim, he would go swimming with us.','["He can''t swim. If he could swim, he would swim with us."]','["he", "can", "swim", "not", "if", "could", "would", "go", "with", "us"]','can → could trong mệnh đề If loại 2.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-006','second-conditional','B1',2,'Nếu hôm nay là Chủ nhật, tôi sẽ ngủ cả ngày.','If today were Sunday, I would sleep all day.','["If today was Sunday, I would sleep all day.", "If it were Sunday today, I would sleep all day.", "If it was Sunday today, I would sleep all day.", "I would sleep all day if today were Sunday.", "I would sleep all day if today was Sunday."]','["if", "today", "be", "Sunday", "I", "would", "sleep", "all day"]','Trái với hiện tại: If + were, would + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-007','second-conditional','B1',2,'Bạn sẽ làm gì nếu bạn là tổng thống?','What would you do if you were the president?','["If you were the president, what would you do?"]','["what", "would", "you", "do", "if", "be", "president"]','Câu hỏi: What would + S + do + if + quá khứ?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-008','second-conditional','B1',2,'Tôi sống xa biển. Nếu sống gần biển, tôi sẽ đi bơi mỗi ngày.','I live far from the sea. If I lived near the sea, I would go swimming every day.','["I live far from the sea. If I lived near the sea, I would swim every day.", "I live far from the beach. If I lived near the beach, I would go swimming every day."]','["I", "live", "far from", "sea", "if", "near", "would", "go", "swim", "every day"]','Trái với thực tế → If + quá khứ (lived), would + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-009','second-conditional','B1',3,'Tôi đang bận. Nếu không bận, tôi sẽ đi xem phim với bạn.','I''m busy. If I weren''t busy, I would go to the cinema with you.','["I''m busy. If I wasn''t busy, I would go to the cinema with you.", "I''m busy. If I weren''t busy, I would go to the movies with you.", "I''m busy. If I wasn''t busy, I would go to the movies with you."]','["I", "be", "busy", "if", "not", "would", "go", "cinema", "with", "you"]','Phủ định trong mệnh đề If: weren''t/wasn''t.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-second-conditional-010','second-conditional','B1',3,'Nếu con người có thể bay, chúng ta sẽ không cần ô tô.','If people could fly, we wouldn''t need cars.','["If humans could fly, we wouldn''t need cars.", "We wouldn''t need cars if people could fly.", "We wouldn''t need cars if humans could fly."]','["if", "person", "can", "fly", "we", "would", "need", "car", "not"]','If + could, wouldn''t + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-001','passive-voice','B1',1,'Tiếng Anh được nói ở nhiều quốc gia.','English is spoken in many countries.',NULL,'["English", "be", "speak", "in", "many", "country"]','Bị động hiện tại: is/are + V3 (speak → spoken).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-002','passive-voice','B1',1,'Ngôi nhà này được xây năm 1990.','This house was built in 1990.',NULL,'["this", "house", "be", "build", "in", "1990"]','Bị động quá khứ: was/were + V3 (build → built).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-003','passive-voice','B1',1,'Những bức ảnh này được chụp bởi bố tôi.','These photos were taken by my father.','["These photos were taken by my dad.", "These pictures were taken by my father.", "These pictures were taken by my dad."]','["this", "photo", "be", "take", "by", "my", "father"]','were + V3 + by + người thực hiện.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-004','passive-voice','B1',1,'Phòng học được dọn dẹp mỗi ngày.','The classroom is cleaned every day.',NULL,'["classroom", "be", "clean", "every day"]','Việc lặp lại → bị động hiện tại: is + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-005','passive-voice','B1',2,'Lúa gạo được trồng ở nhiều nơi tại Việt Nam.','Rice is grown in many places in Vietnam.','["Rice is grown in many parts of Vietnam.", "Rice is grown in many places in Viet Nam."]','["rice", "be", "grow", "in", "many", "place", "Vietnam"]','grow → grown; rice không đếm được → is.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-006','passive-voice','B1',2,'Hôm qua chiếc xe đạp của tôi đã bị đánh cắp.','My bike was stolen yesterday.','["Yesterday my bike was stolen.", "My bicycle was stolen yesterday.", "Yesterday my bicycle was stolen."]','["my", "bike", "be", "steal", "yesterday"]','Bị động quá khứ: was + V3 (steal → stolen).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-007','passive-voice','B1',2,'Những chiếc ô tô này không được sản xuất ở Nhật Bản.','These cars are not made in Japan.','["These cars are not produced in Japan.", "These cars are not manufactured in Japan."]','["this", "car", "be", "make", "in", "Japan", "not"]','Phủ định bị động: are not + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-008','passive-voice','B1',2,'Cuốn sách này được viết khi nào?','When was this book written?',NULL,'["when", "be", "this", "book", "write"]','Câu hỏi bị động: When + was + S + V3?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-009','passive-voice','B1',3,'Chiếc điện thoại này được sản xuất ở đâu?','Where is this phone made?','["Where was this phone made?", "Where is this phone produced?", "Where is this phone manufactured?"]','["where", "be", "this", "phone", "make"]','Câu hỏi bị động: Where + is + S + V3?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-passive-voice-010','passive-voice','B1',3,'Các kim tự tháp đã được xây từ hàng nghìn năm trước.','The pyramids were built thousands of years ago.',NULL,'["pyramid", "be", "build", "thousands of years ago"]','ago → bị động quá khứ: were + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-001','reported-speech','B1',1,'Cô ấy nói rằng cô ấy mệt.','She said that she was tired.','["She said she was tired."]','["she", "say", "that", "be", "tired"]','Lùi thì: is → was.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-002','reported-speech','B1',1,'Anh ấy nói rằng anh ấy thích bóng đá.','He said that he liked football.','["He said he liked football.", "He said that he liked soccer.", "He said he liked soccer."]','["he", "say", "that", "like", "football"]','Lùi thì: like → liked.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-003','reported-speech','B1',1,'Tom nói rằng anh ấy đang làm bài tập về nhà.','Tom said that he was doing his homework.','["Tom said he was doing his homework.", "Tom said that he was doing homework.", "Tom said he was doing homework."]','["Tom", "say", "that", "he", "be", "do", "his", "homework"]','Lùi thì: am doing → was doing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-004','reported-speech','B1',1,'Mai nói với tôi rằng cô ấy sẽ đến muộn.','Mai told me that she would be late.','["Mai told me she would be late.", "Mai told me that she would come late.", "Mai told me she would come late."]','["Mai", "tell", "me", "that", "she", "will", "be", "late"]','Lùi thì: will → would; tell + người nghe.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-005','reported-speech','B1',2,'Họ nói rằng họ đã xem bộ phim đó rồi.','They said that they had already seen that film.','["They said they had already seen that film.", "They said that they had already seen that movie.", "They said they had already seen that movie.", "They said that they had seen that film already.", "They said they had seen that film already."]','["they", "say", "that", "have", "already", "see", "that", "film"]','Lùi thì: have seen → had seen.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-006','reported-speech','B1',2,'Cô giáo nói rằng bài kiểm tra rất khó.','The teacher said that the test was very difficult.','["The teacher said the test was very difficult.", "The teacher said that the test was very hard.", "The teacher said the test was very hard."]','["teacher", "say", "that", "test", "be", "very", "difficult"]','Lùi thì: is → was.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-007','reported-speech','B1',2,'Nam nói rằng anh ấy không thể đến bữa tiệc.','Nam said that he couldn''t come to the party.','["Nam said he couldn''t come to the party.", "Nam said that he couldn''t go to the party.", "Nam said he couldn''t go to the party."]','["Nam", "say", "that", "he", "can", "come", "to", "party", "not"]','Lùi thì: can''t → couldn''t.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-008','reported-speech','B1',2,'Mẹ tôi nói rằng mẹ đã nấu bữa tối rồi.','My mother said that she had already cooked dinner.','["My mother said she had already cooked dinner.", "My mum said that she had already cooked dinner.", "My mum said she had already cooked dinner.", "My mom said that she had already cooked dinner.", "My mom said she had already cooked dinner.", "My mother said that she had already made dinner.", "My mother said she had already made dinner."]','["my", "mother", "say", "that", "she", "have", "already", "cook", "dinner"]','Lùi thì: have cooked → had cooked.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-009','reported-speech','B1',3,'Anh ấy nói với tôi rằng anh ấy sống ở Hà Nội.','He told me that he lived in Hanoi.','["He told me he lived in Hanoi.", "He told me that he lived in Ha Noi.", "He told me he lived in Ha Noi."]','["he", "tell", "me", "that", "live", "in", "Hanoi"]','told + người nghe; lùi thì: live → lived.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-reported-speech-010','reported-speech','B1',3,'Lan nói rằng cô ấy có thể nói ba thứ tiếng.','Lan said that she could speak three languages.','["Lan said she could speak three languages."]','["Lan", "say", "that", "she", "can", "speak", "three", "language"]','Lùi thì: can → could.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-001','relative-clauses-defining','B1',1,'Đây là cậu bé đã giúp tôi.','This is the boy who helped me.','["This is the boy that helped me."]','["this", "be", "boy", "who", "help", "me"]','Chỉ người → who (hoặc that).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-002','relative-clauses-defining','B1',1,'Tôi thích những cuốn sách có kết thúc có hậu.','I like books which have happy endings.','["I like books that have happy endings."]','["I", "like", "book", "which", "have", "happy", "ending"]','Chỉ vật → which (hoặc that).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-003','relative-clauses-defining','B1',1,'Người phụ nữ sống cạnh nhà tôi là một bác sĩ.','The woman who lives next to my house is a doctor.','["The woman that lives next to my house is a doctor.", "The woman who lives next door to me is a doctor.", "The woman that lives next door to me is a doctor."]','["woman", "who", "live", "next to", "my", "house", "be", "doctor"]','Mệnh đề who bổ nghĩa cho the woman.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-004','relative-clauses-defining','B1',1,'Đây là chiếc điện thoại mà tôi đã mua hôm qua.','This is the phone that I bought yesterday.','["This is the phone which I bought yesterday.", "This is the phone I bought yesterday."]','["this", "be", "phone", "that", "I", "buy", "yesterday"]','Chỉ vật làm tân ngữ → that/which (có thể lược bỏ).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-005','relative-clauses-defining','B1',2,'Bạn có biết người đàn ông đang nói chuyện với cô giáo không?','Do you know the man who is talking to the teacher?','["Do you know the man that is talking to the teacher?", "Do you know the man who is talking with the teacher?", "Do you know the man that is talking with the teacher?"]','["you", "know", "man", "who", "talk", "to", "teacher"]','Chỉ người → who.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-006','relative-clauses-defining','B1',2,'Con mèo đã bắt được con chuột là của tôi.','The cat that caught the mouse is mine.','["The cat which caught the mouse is mine."]','["cat", "that", "catch", "mouse", "be", "mine"]','Chỉ con vật → that/which.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-007','relative-clauses-defining','B1',2,'Đó là nhà hàng nơi chúng tôi đã ăn tối tuần trước.','That is the restaurant where we had dinner last week.','["That is the restaurant where we ate dinner last week."]','["that", "be", "restaurant", "where", "we", "have", "dinner", "last week"]','Chỉ nơi chốn → where.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-008','relative-clauses-defining','B1',2,'Tôi có một người bạn biết nói tiếng Nhật.','I have a friend who can speak Japanese.','["I have a friend that can speak Japanese.", "I have a friend who speaks Japanese.", "I have a friend that speaks Japanese."]','["I", "have", "friend", "who", "can", "speak", "Japanese"]','Chỉ người → who.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-009','relative-clauses-defining','B1',3,'Bộ phim mà chúng ta đã xem tối qua rất hay.','The film that we watched last night was very good.','["The film which we watched last night was very good.", "The film we watched last night was very good.", "The movie that we watched last night was very good.", "The movie which we watched last night was very good.", "The movie we watched last night was very good."]','["film", "that", "we", "watch", "last night", "be", "very", "good"]','Mệnh đề quan hệ đứng ngay sau danh từ nó bổ nghĩa.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-relative-clauses-defining-010','relative-clauses-defining','B1',3,'Ông ấy là người đàn ông có con trai là ca sĩ nổi tiếng.','He is the man whose son is a famous singer.',NULL,'["he", "be", "man", "whose", "son", "famous", "singer"]','Chỉ sở hữu → whose + danh từ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-001','gerund-infinitive','B1',1,'Tôi muốn trở thành bác sĩ.','I want to become a doctor.','["I want to be a doctor."]','["I", "want", "become", "doctor"]','want + to V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-002','gerund-infinitive','B1',1,'Cô ấy đã quyết định học tiếng Pháp.','She decided to learn French.','["She decided to study French.", "She has decided to learn French.", "She has decided to study French."]','["she", "decide", "learn", "French"]','decide + to V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-003','gerund-infinitive','B1',1,'Anh ấy đã bỏ hút thuốc.','He stopped smoking.','["He has stopped smoking.", "He quit smoking.", "He has quit smoking.", "He gave up smoking.", "He has given up smoking."]','["he", "stop", "smoke"]','stop + V-ing = ngừng hẳn việc đó.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-004','gerund-infinitive','B1',1,'Bạn có phiền mở cửa sổ không?','Would you mind opening the window?','["Do you mind opening the window?"]','["you", "mind", "open", "window"]','mind + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-005','gerund-infinitive','B1',2,'Bơi lội rất tốt cho sức khỏe.','Swimming is very good for your health.','["Swimming is very good for health.", "Swimming is very good for you."]','["swim", "be", "very", "good", "for", "health"]','V-ing làm chủ ngữ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-006','gerund-infinitive','B1',2,'Chúng tôi hy vọng sớm gặp lại bạn.','We hope to see you again soon.',NULL,'["we", "hope", "see", "you", "again", "soon"]','hope + to V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-007','gerund-infinitive','B1',2,'Tôi đã quên khóa cửa.','I forgot to lock the door.',NULL,'["I", "forget", "lock", "door"]','forget + to V = quên làm việc cần làm.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-008','gerund-infinitive','B1',2,'Cô ấy tránh ăn đồ ngọt.','She avoids eating sweet food.','["She avoids eating sweets.", "She avoids eating sugary food."]','["she", "avoid", "eat", "sweet", "food"]','avoid + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-009','gerund-infinitive','B1',3,'Anh ấy gợi ý đi xem phim.','He suggested going to the cinema.','["He suggested going to the movies."]','["he", "suggest", "go", "cinema"]','suggest + V-ing.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-gerund-infinitive-010','gerund-infinitive','B1',3,'Tôi rất mong được gặp bạn.','I''m looking forward to meeting you.','["I''m looking forward to seeing you.", "I look forward to meeting you.", "I look forward to seeing you."]','["I", "look forward to", "meet", "you"]','look forward to + V-ing (to là giới từ).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-001','used-to','B1',1,'Tôi từng sống ở nông thôn.','I used to live in the countryside.','["I used to live in the country."]','["I", "used to", "live", "in", "countryside"]','Thói quen/trạng thái trong quá khứ: used to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-002','used-to','B1',1,'Hồi nhỏ, cô ấy từng sợ bóng tối.','When she was little, she used to be afraid of the dark.','["She used to be afraid of the dark when she was little.", "When she was young, she used to be afraid of the dark.", "She used to be afraid of the dark when she was young.", "When she was little, she used to be scared of the dark.", "She used to be scared of the dark when she was little."]','["when", "she", "be", "little", "used to", "afraid", "of", "dark"]','used to + be + adj.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-003','used-to','B1',1,'Ông tôi từng hút thuốc.','My grandfather used to smoke.','["My grandpa used to smoke."]','["my", "grandfather", "used to", "smoke"]','used to + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-004','used-to','B1',1,'Chúng tôi từng chơi với nhau mỗi ngày.','We used to play together every day.',NULL,'["we", "used to", "play", "together", "every day"]','used to: việc hay làm trước đây, nay không còn.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-005','used-to','B1',2,'Trước đây anh ấy không thích rau.','He didn''t use to like vegetables.','["He used not to like vegetables."]','["he", "use to", "like", "vegetable", "not"]','Phủ định: didn''t use to + V (không có -d).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-006','used-to','B1',2,'Trước đây tôi không uống cà phê.','I didn''t use to drink coffee.','["I used not to drink coffee."]','["I", "use to", "drink", "coffee", "not"]','didn''t use to + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-007','used-to','B1',2,'Hồi nhỏ bạn có từng trèo cây không?','Did you use to climb trees when you were little?','["Did you use to climb trees when you were young?", "Did you use to climb trees when you were a child?", "When you were little, did you use to climb trees?"]','["you", "use to", "climb", "tree", "when", "be", "little"]','Câu hỏi: Did + S + use to + V?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-008','used-to','B1',2,'Ngày xưa ở đây từng có một rạp chiếu phim.','There used to be a cinema here.','["There used to be a movie theater here.", "There used to be a movie theatre here."]','["there", "used to", "be", "cinema", "here"]','There used to be + N.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-009','used-to','B1',3,'Bố tôi từng chơi bóng đá cho đội của trường.','My father used to play football for the school team.','["My dad used to play football for the school team.", "My father used to play soccer for the school team.", "My dad used to play soccer for the school team."]','["my", "father", "used to", "play", "football", "for", "school", "team"]','used to + V nguyên thể.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-used-to-010','used-to','B1',3,'Mẹ tôi từng đi làm bằng xe đạp, nhưng bây giờ mẹ đi xe máy.','My mother used to go to work by bike, but now she goes by motorbike.','["My mum used to go to work by bike, but now she goes by motorbike.", "My mom used to go to work by bike, but now she goes by motorbike.", "My mother used to go to work by bicycle, but now she goes by motorbike.", "My mother used to cycle to work, but now she goes by motorbike."]','["my", "mother", "used to", "go", "work", "by", "bike", "but", "now", "motorbike"]','used to (quá khứ) đối lập với hiện tại đơn (now she goes).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-001','third-conditional','B2',1,'Nếu tôi học chăm hơn, tôi đã đỗ kỳ thi rồi.','If I had studied harder, I would have passed the exam.','["I would have passed the exam if I had studied harder."]','["if", "I", "have", "study", "hard", "would", "pass", "exam"]','Trái với quá khứ: If + had + V3, would have + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-002','third-conditional','B2',1,'Nếu sáng nay cô ấy dậy sớm hơn, cô ấy đã không bị lỡ xe buýt.','If she had got up earlier this morning, she wouldn''t have missed the bus.','["If she had gotten up earlier this morning, she wouldn''t have missed the bus.", "If she had woken up earlier this morning, she wouldn''t have missed the bus.", "She wouldn''t have missed the bus if she had got up earlier this morning.", "She wouldn''t have missed the bus if she had gotten up earlier this morning."]','["if", "she", "have", "get up", "early", "this morning", "would", "miss", "bus", "not"]','wouldn''t have + V3 cho kết quả trái với quá khứ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-003','third-conditional','B2',1,'Nếu bạn nói với tôi, tôi đã giúp bạn rồi.','If you had told me, I would have helped you.','["I would have helped you if you had told me."]','["if", "you", "have", "tell", "me", "I", "would", "help"]','If + had + V3, would have + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-004','third-conditional','B2',1,'Nếu hôm qua trời không mưa, chúng tôi đã đi biển rồi.','If it hadn''t rained yesterday, we would have gone to the beach.','["We would have gone to the beach if it hadn''t rained yesterday."]','["if", "it", "have", "rain", "yesterday", "not", "we", "would", "go", "beach"]','If + hadn''t + V3, would have + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-005','third-conditional','B2',2,'Nếu anh ấy không lái xe quá nhanh, tai nạn đã không xảy ra.','If he hadn''t driven so fast, the accident wouldn''t have happened.','["If he hadn''t driven too fast, the accident wouldn''t have happened.", "The accident wouldn''t have happened if he hadn''t driven so fast.", "The accident wouldn''t have happened if he hadn''t driven too fast."]','["if", "he", "have", "drive", "so", "fast", "not", "accident", "would", "happen"]','drive → driven; happen → happened.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-006','third-conditional','B2',2,'Nếu tôi biết bạn bị ốm, tôi đã đến thăm bạn rồi.','If I had known you were ill, I would have visited you.','["If I had known that you were ill, I would have visited you.", "If I had known you were sick, I would have visited you.", "If I had known that you were sick, I would have visited you.", "I would have visited you if I had known you were ill.", "I would have visited you if I had known you were sick."]','["if", "I", "have", "know", "you", "be", "ill", "would", "visit"]','If + had known (trái với quá khứ: thực ra không biết).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-007','third-conditional','B2',2,'Chúng tôi đã thắng nếu thủ môn không bị chấn thương.','We would have won if the goalkeeper hadn''t been injured.','["If the goalkeeper hadn''t been injured, we would have won."]','["we", "would", "win", "if", "goalkeeper", "have", "be", "injure", "not"]','would have won; hadn''t been + V3 (bị động).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-008','third-conditional','B2',2,'Bạn sẽ làm gì nếu hôm đó bạn bị lỡ chuyến bay?','What would you have done if you had missed the flight?','["If you had missed the flight, what would you have done?"]','["what", "would", "you", "have", "do", "if", "miss", "flight"]','Câu hỏi: What would + S + have + V3 + if + had + V3?',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-009','third-conditional','B2',3,'Nếu bố mẹ tôi không gặp nhau ở trường đại học, tôi đã không được sinh ra.','If my parents hadn''t met at university, I wouldn''t have been born.','["I wouldn''t have been born if my parents hadn''t met at university.", "If my parents hadn''t met at college, I wouldn''t have been born."]','["if", "my", "parent", "have", "meet", "at", "university", "not", "I", "would", "be", "born"]','wouldn''t have been born: kết quả trái với quá khứ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-third-conditional-010','third-conditional','B2',3,'Nếu tối qua tôi mang theo ô, tôi đã không bị ướt.','If I had taken an umbrella last night, I wouldn''t have got wet.','["If I had brought an umbrella last night, I wouldn''t have got wet.", "If I had taken an umbrella last night, I wouldn''t have gotten wet.", "If I had brought an umbrella last night, I wouldn''t have gotten wet.", "I wouldn''t have got wet if I had taken an umbrella last night.", "I wouldn''t have gotten wet if I had taken an umbrella last night."]','["if", "I", "have", "take", "umbrella", "last night", "would", "get", "wet", "not"]','If + had + V3, wouldn''t have + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-001','wish-if-only','B2',1,'Tôi ước tôi cao hơn.','I wish I were taller.','["I wish I was taller."]','["I", "wish", "be", "tall"]','Ước trái với hiện tại: wish + quá khứ (were).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-002','wish-if-only','B2',1,'Tôi ước tôi có một con chó.','I wish I had a dog.',NULL,'["I", "wish", "have", "dog"]','wish + quá khứ đơn (had).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-003','wish-if-only','B2',1,'Cô ấy ước cô ấy có thể nói tiếng Anh trôi chảy.','She wishes she could speak English fluently.','["She wishes that she could speak English fluently."]','["she", "wish", "can", "speak", "English", "fluently"]','wish + could + V.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-004','wish-if-only','B2',1,'Tôi ước tối qua tôi đã không ăn nhiều như vậy.','I wish I hadn''t eaten so much last night.','["I wish I hadn''t eaten that much last night."]','["I", "wish", "have", "eat", "so", "much", "last night", "not"]','Ước trái với quá khứ: wish + had + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-005','wish-if-only','B2',2,'Giá mà tôi biết câu trả lời.','If only I knew the answer.',NULL,'["if only", "I", "know", "answer"]','If only + quá khứ đơn: ước cho hiện tại.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-006','wish-if-only','B2',2,'Giá mà hôm qua tôi đã nghe lời mẹ.','If only I had listened to my mother yesterday.','["If only I had listened to my mum yesterday.", "If only I had listened to my mom yesterday."]','["if only", "I", "have", "listen", "to", "my", "mother", "yesterday"]','If only + had + V3: tiếc về quá khứ.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-007','wish-if-only','B2',2,'Tôi ước hôm nay tôi không phải đi học.','I wish I didn''t have to go to school today.',NULL,'["I", "wish", "have to", "go", "school", "today", "not"]','Ước cho hiện tại → didn''t have to.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-008','wish-if-only','B2',2,'Anh ấy ước anh ấy đã học chăm hơn.','He wishes he had studied harder.','["He wishes that he had studied harder."]','["he", "wish", "have", "study", "hard"]','Tiếc về quá khứ → wishes + had + V3.',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-009','wish-if-only','B2',3,'Tôi ước bạn sống gần nhà tôi hơn.','I wish you lived closer to my house.','["I wish you lived nearer to my house.", "I wish you lived closer to me.", "I wish you lived nearer to me."]','["I", "wish", "you", "live", "close", "to", "my", "house"]','wish + S + quá khứ đơn (lived).',1,'live','seed','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO grammar_translate_items (id,grammar_id,cefr,tier,vi,en,accept,word_bank,note_vi,article_lenient,status,source,created_at) VALUES ('gt-wish-if-only-010','wish-if-only','B2',3,'Giá mà trời tạnh mưa.','If only it would stop raining.',NULL,'["if only", "it", "would", "stop", "rain"]','If only + would + V: mong điều gì đó thay đổi.',1,'live','seed','2026-10-27T00:00:00.000Z');
